// Validation et préparation des données (avec support batch)
// v2.1 - 2026-05-01: Ajout normalizeTraite() pour UPDATE cd.traite
const input = $('Webhook Trigger').first().json;
const body = input.body || input;
const headers = input.headers || {};
const projectId = headers['x-project-id'] || body.project_id || body.projectId || (body.context && body.context.project_id) || null;

const startTime = Date.now();

// ============================================
// NORMALISATION TRAITE (UPDATE cd.traite 2026-05-01)
// 7 patterns couvrant ~95% des cas
// Ref: docs/issues/2026-05-01-update-cd-traite-normalization.md
// À SUPPRIMER quand PR feat(vocalization) Option C sera mergée côté API
// ============================================
function normalizeTraite(input) {
  if (!input) return input;
  let m;
  // Pattern 1: "English Explanation of <X>" → "<X>"
  m = input.match(/^English Explanation of (.+)$/);
  if (m) return m[1];
  // Pattern 2: "Rif <X>" → "<X>"
  m = input.match(/^Rif (.+)$/);
  if (m) return m[1];
  // Pattern 3: "<X>; Alternate Version|Mahadurah Tanina|Second Recension" → "<X>"
  m = input.match(/^(.+); (?:Alternate Version|Mahadurah Tanina|Second Recension)$/);
  if (m) return m[1];
  // Pattern 4: "Mishnah Taanit" → "Mishnah Ta'anit"
  if (input === 'Mishnah Taanit') return "Mishnah Ta'anit";
  // Pattern 5: "Avot" → "Pirkei Avot"
  if (input === 'Avot') return 'Pirkei Avot';
  // Pattern 6: "Mishnah Baba <X>" → "Mishnah Bava <X>"
  m = input.match(/^Mishnah Baba (.+)$/);
  if (m) return `Mishnah Bava ${m[1]}`;
  // Pattern 7: "Jerusalem Talmud, <X>" → "Jerusalem Talmud <X>"
  m = input.match(/^Jerusalem Talmud, (.+)$/);
  if (m) return `Jerusalem Talmud ${m[1]}`;
  // Default: pass-through (déjà canonique)
  return input;
}

// Extraction des paramètres
const openaiApiKey = body.openai_api_key || '';
const context = body.context || {};

// ── Fournisseur de la VOCALISATION (azy.daily#642, « Il faut le changer aussi ») ──
// Jusqu'ici `gpt-4o` était littéral dans le nœud HTTP, qui tapait
// api.openai.com. L'appel passe désormais par /webhook/llm-call-messages, donc
// openai | anthropic | google.
//
// ⚠️ Le défaut est `openai` + `gpt-4o`, PAS `anthropic` : c'est le comportement
// d'aujourd'hui, et l'invite est calibrée sur ce modèle. Un appelant qui n'envoie
// rien doit obtenir exactement ce qu'il obtenait hier, à la nekuda près.
// ⚠️ Gemini se nomme `google`, pas `gemini` — énumération de llm-call-messages.
const FOURNISSEURS = ['anthropic', 'openai', 'google', 'mistral', 'ollama-cloud'];
const provider = String(body.provider || 'openai').toLowerCase();
const model = body.model || 'gpt-4o';
// BYOT, aucun repli d'environnement. `openai_api_key` reste la clé historique.
const providerCle = body.provider_api_key
  || (provider === 'openai' ? openaiApiKey : null)
  || body.plugin_context?.api_keys?.[provider]
  || null;

// ── Raisonnement de la vocalisation (azy.daily#706) ──────────────────────────
// Mesuré le 2026-11-22, exécution 1313618 : `gpt-5-mini` a dépensé la TOTALITÉ du
// budget en raisonnement — budget = completion_tokens = reasoning_tokens, 71/71,
// `finish_reason: 'length'`, 0 caractère rendu, en HTTP 200. ≈ 0,40 $ pour deux
// pages, et aucune alerte crédits : le garde-fou plugin a bloqué l'écriture, donc
// l'argent part chez le fournisseur sans trace interne.
//
// ⚠️ AUGMENTER LE BUDGET NE CORRIGE RIEN : le raisonnement s'étend pour occuper ce
// qu'on lui offre (texte 2 290 car → budget 4 580 → 4 580 de raisonnement, texte 0).
// Le seul levier est l'EFFORT. Et la vocalisation n'a aucun besoin de réfléchir :
// c'est une réécriture LOCALE au mot — l'argument même qui rend le découpage sûr
// (voir `Découper Texte`).
//
// PASSE-PLAT, comme `provider` et `model` : le relais `llm-call-messages` sait déjà
// placer ces deux champs chez chaque fournisseur (azy.daily#365) — tel quel en
// chat/completions, `reasoning.effort` sur /v1/responses, `thinkingConfig` chez
// Gemini, `completion_args` chez Mistral. On ne les INTERPRÈTE donc pas ici.
const reasoningConfigBrut = body.reasoning_config ?? context.reasoning_config ?? null;
const reasoningConfig = (reasoningConfigBrut !== null
  && typeof reasoningConfigBrut === 'object'
  && !Array.isArray(reasoningConfigBrut)) ? reasoningConfigBrut : null;
// ⚠️ Le refus est poussé plus bas, avec les autres : `errors` n'existe pas encore
// ici, et `errors.push` d'ici lève une ReferenceError que `node --check` ne voit pas.
const reasoningConfigInvalide = (reasoningConfigBrut !== null && reasoningConfig === null);
const effortDemande = body.reasoning_effort ?? context.reasoning_effort;
const effortAppelant = (typeof effortDemande === 'string' && effortDemande.trim())
  ? effortDemande.trim() : null;

// ⚠️ LE DÉFAUT NE PEUT PAS ÊTRE INCONDITIONNEL. Envoyer `reasoning_effort` avec
// `gpt-4o` fait basculer le relais en mode raisonnement : il remplace `max_tokens`
// par `max_completion_tokens`, RETIRE `temperature` (0.1 ici), et OpenAI refuse le
// paramètre lui-même (400 « Unsupported parameter »). Le défaut d'aujourd'hui
// (openai + gpt-4o, invite calibrée dessus) doit rendre exactement ce qu'il rendait
// hier, à la nekuda près.
//
// Discriminant repris TEL QUEL du relais (`LLM - Call Messages`, `Validate Input`)
// pour que les deux ne divergent pas. ⚠️ Il DEVINE sur l'identifiant, et le relais
// le dit lui-même : « chat.api connaît la capacité du modèle, nous la devinons ;
// deviner sur l'identifiant est un pis-aller qui rate ce qu'il ne reconnaît pas ».
// Un modèle raisonnant qu'il ne reconnaît pas repasse donc par le défaut du modèle
// — c'est `Recoller Vocalisation` qui le nomme alors, signature à l'appui.
const MODELE_RAISONNEMENT = /^(?:openai\/)?(?:chat)?gpt-5|^(?:openai\/)?o[1-9]/i;
const modeleRaisonne = provider === 'openai'
  && MODELE_RAISONNEMENT.test(String(model || '').trim());
// L'appelant prime toujours : il a le catalogue, nous avons une expression régulière.
const reasoningEffort = effortAppelant || (modeleRaisonne ? 'minimal' : null);


// Normaliser traite si présent dans le contexte
const normalizedTraite = context.traite ? normalizeTraite(context.traite) : null;
const traiteWasNormalized = normalizedTraite && normalizedTraite !== context.traite;

// Détecter mode batch ou single
const isBatch = Array.isArray(body.items) && body.items.length > 0;

// Validation
const errors = [];

if (FOURNISSEURS.indexOf(provider) === -1) {
  errors.push('Le champ "provider" doit valoir ' + FOURNISSEURS.join(', ')
    + ' et Gemini se nomme google');
}
// Un fragment mal formé est REFUSÉ, jamais deviné : le relais lèverait dessus
// (azy.daily#365), et un fragment deviné enverrait un réglage que personne n'a demandé.
if (reasoningConfigInvalide) {
  errors.push('reasoning_config doit etre un objet');
}
// ⚠️ Assouplissement : il faut une clé POUR LE FOURNISSEUR CHOISI, et non plus
// une clé OpenAI. Sans `provider`, c'est openai — donc `openai_api_key` seul
// suffit encore, exactement comme avant.
if (!providerCle) {
  errors.push(provider === 'openai'
    ? 'Le champ "openai_api_key" est requis'
    : 'Aucune cle pour le fournisseur ' + provider
      + ' — fournir "provider_api_key" ou "plugin_context.api_keys.' + provider + '"');
}

if (isBatch) {
  // Validation batch
  for (let i = 0; i < body.items.length; i++) {
    const item = body.items[i];
    if (!item.text || item.text.trim().length === 0) {
      errors.push(`Item ${i}: le champ "text" est requis`);
    }
  }
} else {
  // Validation single (existant)
  const text = body.text || '';
  if (!text || text.trim().length === 0) {
    errors.push('Le champ "text" est requis');
  }
}

// === MODE SINGLE (rétrocompatibilité) ===
if (!isBatch) {
  const text = body.text || '';
  const segmentId = body.segment_id || null;
  const sourceTextId = body.source_text_id || null;
  const commentaryId = body.commentary_id || null;

  let cacheSearchParams = '';
  if (segmentId) {
    cacheSearchParams = `segment_id=${segmentId}`;
  } else if (sourceTextId) {
    cacheSearchParams = `source_text_id=${sourceTextId}`;
  } else if (commentaryId) {
    cacheSearchParams = `commentary_id=${commentaryId}`;
  } else if (normalizedTraite && context.page) {
    // Utiliser le traite normalisé pour la recherche cache
    cacheSearchParams = `traite=${encodeURIComponent(normalizedTraite)}&page=${encodeURIComponent(context.page)}`;
    if (context.commentator) {
      cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
    }
  }

  return [{
    json: {
      valid: errors.length === 0,
      errors: errors,
      isBatch: false,
      text: text,
      openaiApiKey: openaiApiKey,
      provider: provider,
      model: model,
      providerCle: providerCle,
      reasoningEffort: reasoningEffort,
      reasoningConfig: reasoningConfig,
      segmentId: segmentId,
      sourceTextId: sourceTextId,
      commentaryId: commentaryId,
      context: context,
      normalizedTraite: normalizedTraite,
      traiteWasNormalized: traiteWasNormalized,
      startTime: startTime,
      cacheSearchParams: cacheSearchParams,
      canSearchCache: !!(segmentId || sourceTextId || commentaryId || (normalizedTraite && context.page)),
      isCommentary: !!commentaryId
    }
  }];
}

// === MODE BATCH ===
const items = body.items.map((item, index) => ({
  index,
  text: item.text,
  segment_id: item.segment_id || null,
  commentary_id: item.commentary_id || null,
  source_text_id: item.source_text_id || null
}));

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    isBatch: true,
    items: items,
    itemCount: items.length,
    openaiApiKey: openaiApiKey,
    provider: provider,
    model: model,
    providerCle: providerCle,
    reasoningEffort: reasoningEffort,
    reasoningConfig: reasoningConfig,
    context: context,
    normalizedTraite: normalizedTraite,
    traiteWasNormalized: traiteWasNormalized,
    startTime: startTime,
    projectId: projectId,
    job_id: body.job_id || null
  }
}];

// Vérifier si le cache a retourné une vocalisation
const input = $input.first().json;
const _vi = $('Validate Input').first().json;
const prevData = _vi.isBatch ? $('Process Batch Item').first().json : _vi;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Cache hit si status 200 et vocalisation trouvée
const cacheHit = statusCode === 200 && data.found === true && data.vocalized_text;

if (cacheHit) {
  return [{
    json: {
      cacheHit: true,
      vocalizedText: data.vocalized_text,
      vocalizedBy: data.vocalized_by || 'cached',
      vocalizedAt: data.vocalized_at,
      // Passer les données pour la réponse
      originalText: prevData.text,
      sourceTextId: data.source_text_id || prevData.sourceTextId,
      commentaryId: data.commentary_id || prevData.commentaryId,
      context: prevData.context,
      startTime: prevData.startTime
    }
  }];
}

// Cache miss - passer au LLM
return [{
  json: {
    cacheHit: false,
    ...prevData
  }
}];

// Formater la réponse depuis le cache
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    vocalization: {
      original: input.originalText,
      vocalized: input.vocalizedText
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      source_text_id: input.sourceTextId || null,
      commentary_id: input.commentaryId || null,
      vocalized_by: input.vocalizedBy,
      source: 'cache',
      cached_at: input.vocalizedAt,
      processing_time_ms: processingTime
    }
  }
}];

