={{ (() => {
  const effort = $json.reasoningEffort || null;
  const fragment = $json.reasoningConfig || null;
  const raisonne = !!(effort || fragment);

  // ⚠️ MARGE DE RAISONNEMENT (azy.daily#706). Le budget est dimensionne sur le
  // TEXTE (2 jetons par caractere : la vocalisation reecrit tout, chaque nekuda
  // etant un codepoint distinct). Il n'a donc AUCUNE slack pour les jetons de
  // raisonnement, meme en 'minimal'. Sans cette marge, le meme echec revient en
  // plus discret -- texte tronque au lieu de vide -- et `Recoller Vocalisation`
  // rejette alors le commentaire entier.
  const budget = Math.min(16000,
    Math.max(1024, Math.ceil($json.text.length * 2)) + (raisonne ? 1024 : 0));

  const corps = {
    provider: $json.provider,
    model: $json.model,
    api_key: $json.providerCle,
    temperature: 0.1,
    max_tokens: budget,
    system: 'Tu es un expert en hébreu biblique et rabbinique. Ta tâche est d\'ajouter les nekudot (voyelles hébraïques/signes de vocalisation) au texte hébreu fourni. Retourne UNIQUEMENT le texte vocalisé, sans explication ni commentaire.',
    messages: [ { role: 'user', content: 'Ajoute les nekudot (voyelles hébraïques) à ce texte:\n\n' + $json.text } ]
  };

  // Rien envoye -> rien ajoute -> defaut du modele, exactement comme avant ce
  // correctif. Le relais place ensuite chaque champ chez son fournisseur
  // (azy.daily#365) et remplace `max_tokens` par `max_completion_tokens` quand il
  // detecte un raisonnement, en retirant `temperature` lui-meme.
  if (effort) { corps.reasoning_effort = effort; }
  if (fragment) { corps.reasoning_config = fragment; }
  return JSON.stringify(corps);
})() }}

