// Finalise un item APRÈS tentative de save (branche « sauvegarde »).
// Vérifie que la vocalisation a RÉELLEMENT été persistée : un échec de save ne
// doit PAS passer pour un succès. azy.daily#150 — 0 ligne persistée sur ~1M
// commentaires, car l'échec était avalé (onError) et Clean Response ne regardait
// jamais le résultat du save.
const item = $('Extract GPT Response').first().json;
const response = { ...item };
delete response._saveData;

// $input = réponse de « Save to Cache » pour l'item courant.
// L'API renvoie { success: true, vocalized_at } quand l'UPDATE a eu lieu.
const saveResult = $input.first().json;
const persisted = saveResult && (saveResult.success === true || !!saveResult.vocalized_at);
if (!persisted) {
  response.success = false;
  response.error = {
    code: 'SAVE_FAILED',
    message: 'vocalisation générée mais NON persistée en base',
    detail: (saveResult && (saveResult.message || saveResult.error || saveResult.detail)) || null
  };
}
return [{ json: response }];

// ============================================
// DÉCOUPER TEXTE — une tranche par appel GPT
// ============================================
//
// La vocalisation est une opération LOCALE : les nekudot d'un mot dépendent de ce
// mot et de son voisinage immédiat, jamais du document entier. Découper est donc
// sûr ici, contrairement à une traduction où la coupure perd le contexte.
//
// Pourquoi c'est nécessaire (mesuré sur l'exécution 746039) :
//
//     durée ≈ 2,1 s + 13,7 ms/caractère       (~65 car/s, débit de génération)
//
//     513 car →  9,2 s        2 237 car → 32,8 s
//     650 car → 11,5 s        5 224 car → 74 s prédites, TIMEOUT à 60 s
//
// Le débit ne dépend pas de la longueur : la vocalisation réécrit le texte entier,
// chaque nekuda étant un codepoint distinct. Le seuil de rupture est à ~4 200
// caractères. Augmenter le timeout ne ferait que déplacer le mur — et exposerait
// à la troncature du modèle, qui n'émet aucune erreur.
//
// Le nœud HTTP en aval traite un item par tranche, séquentiellement. Son timeout
// couvre l'ENSEMBLE des items d'une exécution, pas chacun : il est donc calibré
// sur le cumul, pas sur une tranche.

const TAILLE_TRANCHE = 2500;

const item = $input.first().json;
const texte = item.text || '';

// Découpe aux frontières de phrase. Les bornes sont des INDEX, et les tranches des
// slices : leur concaténation redonne exactement le texte d'origine, sans qu'un
// séparateur ne se perde en route.
function bornes(t, taille) {
  if (t.length <= taille) return [[0, t.length]];
  // Fins de phrase, y compris le sof pasuq et le sof passuk hébreux.
  const fins = [];
  const re = /[.!?׃:]\s+|\n+/g;
  let m;
  while ((m = re.exec(t)) !== null) fins.push(m.index + m[0].length);
  // Repli : frontières de mot, si le texte n'a aucune ponctuation exploitable.
  if (fins.length === 0) {
    const rw = /\s+/g;
    while ((m = rw.exec(t)) !== null) fins.push(m.index + m[0].length);
  }
  fins.push(t.length);

  const res = [];
  let debut = 0;
  let derniere = 0;
  for (const f of fins) {
    if (f - debut > taille && derniere > debut) {
      res.push([debut, derniere]);
      debut = derniere;
    }
    derniere = f;
  }
  if (debut < t.length) res.push([debut, t.length]);
  // Dernier recours : une tranche sans aucune frontière interne reste trop
  // longue — on coupe net plutôt que de la laisser expirer.
  const fin = [];
  for (const [a, b] of res) {
    if (b - a <= taille * 1.5) { fin.push([a, b]); continue; }
    for (let x = a; x < b; x += taille) fin.push([x, Math.min(x + taille, b)]);
  }
  return fin;
}

const decoupe = bornes(texte, TAILLE_TRANCHE);
const tranches = decoupe.map(([a, b]) => texte.slice(a, b));

return tranches.map((t, i) => ({ json: Object.assign({}, item, {
  text: t,
  _tranche: i,
  _nbTranches: tranches.length,
  _texteComplet: texte
})}));

// ============================================
// RECOLLER VOCALISATION — N tranches → une réponse
// ============================================
//
// Rend un objet de la FORME DE L'ENVELOPPE de llm-call-messages, pour que
// « Extract GPT Response » reste le seul endroit qui interprète le résultat.
// (Avant azy.daily#642 : la forme brute d'OpenAI, l'appel étant direct.)
//
// Trois garde-fous :
//
//  1. finish_reason — un texte tronqué par le modèle sortait en success:true et
//     partait en base : des nekudot manquantes en fin de texte, sans erreur.
//  2. tranche en échec — recoller les survivantes donnerait un texte AMPUTÉ
//     présenté comme complet.
//  3. réponse vide — une tranche sans contenu vaut échec, pas chaîne vide.
//
// Dans les trois cas on émet un corps d'erreur, qu'« Extract GPT Response »
// reconnaît, donc rien n'est sauvegardé.

// ⚠️⚠️ LE PIÈGE DU PORTAGE MULTI-FOURNISSEURS.
// Les trois fournisseurs ne nomment PAS pareil une génération terminée :
//     OpenAI     'stop'            tronqué → 'length'
//     Anthropic  'end_turn'        tronqué → 'max_tokens'
//     Gemini     'STOP' (MAJUSCULES)  tronqué → 'MAX_TOKENS'
// Le test d'origine était `finish_reason !== 'stop'`. Tel quel, il aurait
// déclaré TRONQUÉE chaque réponse d'Anthropic et de Gemini — la vocalisation
// aurait échoué systématiquement hors OpenAI, en annonçant une troncature qui
// n'existe pas. Diagnostic faux, et cause introuvable sans relire ce nœud.
const FINS_NORMALES = ['stop', 'end_turn', 'stop_sequence'];
const finNormale = (r) => !r || FINS_NORMALES.indexOf(String(r).toLowerCase()) !== -1;

const entrees = $input.all();
const nb = entrees.length;

const morceaux = [];
const soucis = [];
let promptTokens = 0;
let completionTokens = 0;
let providerUtilise = null;
let modelUtilise = null;

for (let i = 0; i < nb; i++) {
  const j = entrees[i].json;

  // Échec de l'appel : sans statusCode, le statut réel est enfoui dans le message.
  let code = j.statusCode;
  if (code === undefined) {
    const brut = String(j?.error?.message || j?.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    code = m ? parseInt(m[1], 10) : ((j?.error || j?.code) ? 502 : 200);
  }
  const env = j.body !== undefined ? j.body : j;

  if (code >= 400 || env.success === false || (env.error && env.error.message)) {
    soucis.push(`tranche ${i + 1}/${nb} — ${env?.error?.message || j?.error?.message || ('HTTP ' + code)}`);
    continue;
  }

  const donnees = env.data || {};
  const contenu = donnees.text;
  const vide = !contenu || !contenu.trim();

  // ⚠️⚠️ L'ORDRE DE CES DEUX GARDE-FOUS EST UN CHOIX — LA CAUSE AVANT LE SYMPTÔME.
  // Jusqu'à azy.daily#706, « texte vide » était testé le PREMIER. Un texte vide
  // AVEC `finish_reason: 'length'` tombait donc dans « réponse vide » et n'atteignait
  // JAMAIS le test suivant : le message nommait le symptôme et cachait la cause,
  // alors que le bon message était écrit juste en dessous. C'est ce qui a fait
  // conclure à l'équipe plugin « un lot de 71 items en un seul appel dépasse la
  // limite » — bonne famille, mauvais mécanisme : il y avait 71 appels DISTINCTS.
  // Ne pas « simplifier » en remettant le vide devant.
  if (!finNormale(donnees.finish_reason)) {
    // Signature du budget avalé par le raisonnement, mesurée 71/71 sur l'exécution
    // 1313618 : budget = completion_tokens = reasoning_tokens, et texte vide. La
    // nommer ICI évite de la rechercher dans les exécutions, qui ne sont gardées
    // qu'au COMPTE (~10 000, soit ~2,4 jours sur une instance occupée).
    const uu = (env.meta || {}).usage || {};
    const avale = vide && uu.reasoning_tokens > 0
      && uu.completion_tokens === uu.reasoning_tokens;
    soucis.push(avale
      ? `tranche ${i + 1}/${nb} — budget de raisonnement avalé (${uu.reasoning_tokens} jetons sur ${uu.completion_tokens} passés à raisonner, finish_reason=${donnees.finish_reason}, texte vide) — baisser reasoning_effort ou prendre un modèle non raisonnant`
      : `tranche ${i + 1}/${nb} — génération interrompue (finish_reason=${donnees.finish_reason}) texte tronqué`);
    continue;
  }
  if (vide) {
    soucis.push(`tranche ${i + 1}/${nb} — réponse vide`);
    continue;
  }

  morceaux.push(contenu.trim());
  const meta = env.meta || {};
  const u = meta.usage || {};
  promptTokens += u.prompt_tokens || 0;
  completionTokens += u.completion_tokens || 0;
  // Provenance réelle : la dernière tranche gagne, elles viennent du même appelant.
  providerUtilise = meta.provider || providerUtilise;
  modelUtilise = meta.model || modelUtilise;
}

if (soucis.length > 0 || morceaux.length !== nb) {
  return [{ json: { statusCode: 200, body: { success: false, error: {
    message: `vocalisation incomplète (${morceaux.length}/${nb} tranches) — ${soucis.join(' ; ')}`
  }}}}];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  data: { text: morceaux.join(' '), model: modelUtilise, finish_reason: 'stop' },
  meta: { provider: providerUtilise, model: modelUtilise,
          usage: { prompt_tokens: promptTokens, completion_tokens: completionTokens } },
  _tranches: nb
}}}];

// ============================================================================
// PRÉPARER FIN VOCALISATION — azy.daily#476
// ============================================================================
//
// La vocalisation ne publiait RIEN : ni `vocalization_complete`, ni aucun autre
// événement. Le plugin ne pouvait que sonder le job, ce qui ne survit pas à la
// fenêtre Discord de quinze minutes sur une boucle de 54 appels séquentiels.
//
// Ce nœud est alimenté par les TROIS points de fin du worker — `Complete Job`,
// `Complete Job (Single)` et `Fail Job` — qui étaient jusqu'ici des fins de
// branche. Les compteurs ne vivent au même endroit que sur le chemin « lot » :
// `$('Merge Batch Results')` n'a pas tourné sur le chemin « élément unique », et
// l'invoquer y lève une exception. D'où le try/catch, qui n'est pas une
// négligence mais la forme que prend « ce nœud n'a pas été exécuté » en n8n.

let total = 1, erreurs = 0;
try {
  const s = $('Merge Batch Results').first().json.summary || {};
  total = Number(s.total) || 0;
  erreurs = Number(s.errors) || 0;
} catch (e) {
  // Chemin élément unique : un seul item, et l'échec se lit sur l'entrée.
  const entree = $input.first().json || {};
  erreurs = (entree.success === false || entree.error) ? 1 : 0;
}
const ok = Math.max(total - erreurs, 0);

const v = $('Validate Input').first().json;

return [{ json: {
  stream: 'llm:results:stream',
  fields: {
    event: 'vocalization_complete',
    correlation_id: v.correlation_id,
    // Même convention que `translation_complete` : TOUT est chaîne (champs de flux
    // Redis), et `success` ne dit QUE « au moins un item est passé ». Le plugin
    // compte sur ok_count / fail_count, jamais sur success.
    success: String(ok > 0),
    job_id: v.job_id || '',
    total: String(total),
    ok_count: String(ok),
    fail_count: String(erreurs),
    error_code: (erreurs === total && total > 0) ? 'ALL_FAILED' : '',
    error_message: erreurs > 0 ? (erreurs + ' item(s) en erreur') : '',
    completed_at: new Date().toISOString()
  },
  max_len: 5000
}}];
